#include <algorithm>
#include <cctype>
#include <cstdint>
#include <string>
#include <vector>

struct Ace { bool allow; std::uint32_t rights; std::string trustee; };

namespace
{
    constexpr std::uint32_t GA{ 0x10000000u }, GR{ 0x80000000u }, GW{ 0x40000000u }, GX{ 0x20000000u };

    bool parseRights(const std::string& s, std::uint32_t& out)
    {
        if (s.rfind("0x", 0) == 0 && s.size() > 2)
        {
            out = 0;
            for (std::size_t i{ 2 }; i < s.size(); ++i)
            {
                if (!std::isxdigit(static_cast<unsigned char>(s[i]))) return false;
                out = out * 16 + static_cast<std::uint32_t>(std::isdigit(static_cast<unsigned char>(s[i])) ? s[i] - '0' : std::tolower(static_cast<unsigned char>(s[i])) - 'a' + 10);
            }
            return true;
        }
        if (s.empty() || s.size() % 2) return false;
        out = 0;
        for (std::size_t i{ 0 }; i < s.size(); i += 2)
        {
            const std::string r{ s.substr(i, 2) };
            if (r == "GA") out |= GA; else if (r == "GR") out |= GR; else if (r == "GW") out |= GW; else if (r == "GX") out |= GX;
            else return false;
        }
        return true;
    }
}

bool parseDacl(const std::string& sddl, std::vector<Ace>& out)
{
    if (sddl.rfind("D:", 0) != 0) return false;
    std::size_t i{ 2 };
    while (i < sddl.size() && sddl[i] != '(') ++i;                       // flags such as P or AI
    std::vector<Ace> aces;
    while (i < sddl.size())
    {
        if (sddl[i] != '(') return false;
        const auto close{ sddl.find(')', i) };
        if (close == std::string::npos) return false;
        std::vector<std::string> f;
        std::string field;
        for (char c : sddl.substr(i + 1, close - i - 1)) { if (c == ';') { f.push_back(field); field.clear(); } else field += c; }
        f.push_back(field);
        if (f.size() != 6 || (f[0] != "A" && f[0] != "D") || f[5].size() != 2) return false;
        Ace a{ f[0] == "A", 0, f[5] };
        if (!parseRights(f[2], a.rights)) return false;
        aces.push_back(a);
        i = close + 1;
    }
    out = aces;
    return true;
}

bool accessCheck(const std::vector<Ace>& dacl, const std::vector<std::string>& groups, std::uint32_t desired)
{
    std::uint32_t granted{ 0 };
    for (const Ace& ace : dacl)
    {
        if (std::find(groups.begin(), groups.end(), ace.trustee) == groups.end()) continue;
        std::uint32_t rights{ ace.rights };
        if (rights & GA) rights = (rights & ~GA) | GR | GW | GX;
        if (!ace.allow) { if (rights & desired & ~granted) return false; }
        else granted |= rights;
        if ((granted & desired) == desired) return true;
    }
    return desired != 0 && (granted & desired) == desired;
}

unitTests:
constexpr std::uint32_t READ = 0x80000000u, WRITE = 0x40000000u;
const std::vector<std::string> admin{ "WD", "AU", "BA" }, user{ "WD", "AU", "IU" }, system_{ "WD", "SY" };
TEST("parsing") {
    std::vector<Ace> d; CHECK(parseDacl("D:P(A;;GA;;;SY)(A;;GA;;;BA)", d)); CHECK_EQ(d.size(), std::size_t{ 2 }); CHECK(d[0].allow); CHECK_EQ(d[1].trustee, std::string("BA")); CHECK_EQ(d[0].rights, 0x10000000u);
    CHECK(parseDacl("D:(A;;GRGW;;;AU)(D;;0x40000000;;;IU)", d)); CHECK_EQ(d[0].rights, READ | WRITE); CHECK(!d[1].allow); CHECK_EQ(d[1].rights, WRITE);
    CHECK(parseDacl("D:", d)); CHECK(d.empty());
    CHECK(!parseDacl("O:BA", d)); CHECK(!parseDacl("D:(A;;GA;;SY)", d)); CHECK(!parseDacl("D:(X;;GA;;;SY)", d)); CHECK(!parseDacl("D:(A;;GZ;;;SY)", d)); CHECK(!parseDacl("D:(A;;GA;;;SY", d));
}
TEST("administrators only") {
    std::vector<Ace> d; parseDacl("D:P(A;;GA;;;SY)(A;;GA;;;BA)", d);
    CHECK(accessCheck(d, admin, READ | WRITE)); CHECK(accessCheck(d, system_, WRITE)); CHECK(!accessCheck(d, user, READ));
}
TEST("deny comes first in effect") {
    std::vector<Ace> d; parseDacl("D:(D;;GW;;;IU)(A;;GRGW;;;AU)", d);
    CHECK(accessCheck(d, user, READ)); CHECK(!accessCheck(d, user, READ | WRITE)); CHECK(accessCheck(d, admin, READ | WRITE));
    std::vector<Ace> late; parseDacl("D:(A;;GRGW;;;AU)(D;;GW;;;IU)", late); CHECK(accessCheck(late, user, READ | WRITE));
}
TEST("nothing granted") { std::vector<Ace> d; parseDacl("D:", d); CHECK(!accessCheck(d, admin, READ)); std::vector<Ace> e; parseDacl("D:(A;;GR;;;BA)", e); CHECK(!accessCheck(e, admin, READ | WRITE)); }

